package thaumcraft.verification;
import java.nio.file.*;import java.util.*;
import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.tick.ServerTickEvent;import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import thaumcraft.registry.*;import thaumcraft.items.*;import thaumcraft.entities.*;import thaumcraft.production.*;import thaumcraft.visnet.*;import thaumcraft.knowledge.*;
final class Round3LiveScene {
 static Path root(){return Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/golems-aura-tools-audit/round3/live");}
 static final BlockPos O=new BlockPos(0,65,0);static ServerPlayer player;static int stage=-1,age;static TravelingTrunk trunk;static ThaumicGolem golem;
 static void register(MinecraftServer server){try{Files.createDirectories(root());Files.deleteIfExists(root().resolve("ready.json"));Files.deleteIfExists(root().resolve("request.json"));}catch(Exception e){throw new RuntimeException(e);}NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedInEvent e)->{if(e.getEntity() instanceof ServerPlayer p){player=p;server.getPlayerList().op(p.getGameProfile());KnowledgeService.initialize(p);KnowledgeService.mutate(p,k->k.completeResearch("INFERNALFURNACE"));}});NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedOutEvent e)->{if(e.getEntity()==player)server.halt(false);});NeoForge.EVENT_BUS.addListener((ServerTickEvent.Post e)->{if(e.getServer()!=server||player==null)return;try{if(stage>=0){age++;if(stage==7&&age%8==0){var drop=new ItemEntity(player.level(),O.getX()+.5,65.2,.5,new ItemStack(Items.APPLE));drop.setNoPickUpDelay();player.level().addFreshEntity(drop);}if(stage==2&&age%30==0)golem.action(6);}var request=root().resolve("request.json");if(!Files.exists(request))return;int next=Integer.parseInt(Files.readString(request).trim());if(next==stage)return;prepare(next);stage=next;age=0;Files.writeString(root().resolve("ready.json"),Integer.toString(stage));}catch(Exception error){error.printStackTrace();server.halt(false);}});}
 static void prepare(int next){var l=player.serverLevel();player.closeContainer();player.stopUsingItem();player.removeAllEffects();player.getInventory().clearContent();for(var slot:EquipmentSlot.values())if(slot.getType()==EquipmentSlot.Type.HUMANOID_ARMOR)player.setItemSlot(slot,ItemStack.EMPTY);for(var entity:l.getEntitiesOfClass(Mob.class,new net.minecraft.world.phys.AABB(O).inflate(25)))entity.discard();for(var entity:l.getEntitiesOfClass(ItemEntity.class,new net.minecraft.world.phys.AABB(O).inflate(25)))entity.discard();for(var p:BlockPos.betweenClosed(O.offset(-8,-1,-8),O.offset(8,7,8)))l.setBlock(p,p.getY()==64?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);l.setDayTime(6000);player.setGameMode(GameType.CREATIVE);player.getAbilities().flying=true;player.onUpdateAbilities();player.teleportTo(.5,65,4.5);player.setYRot(180);player.setXRot(8);player.fallDistance=0;
 switch(next){
 case 0->{for(int x=-2;x<=2;x++)for(int y=0;y<4;y++)l.setBlockAndUpdate(O.offset(x,y,0),Blocks.STONE.defaultBlockState());player.server.getCommands().performPrefixedCommand(player.createCommandSourceStack(),"thaumcraft node");}
 case 1->{for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS)){String suffix=slot==EquipmentSlot.HEAD?"helmet":slot==EquipmentSlot.CHEST?"chestplate":"leggings";player.setItemSlot(slot,new ItemStack(R3Equipment.ARMOR.get("void_robe_"+suffix).get()));}player.setGameMode(GameType.SURVIVAL);}
 case 2->{golem=Round3Verification.golem(l,O,8,GolemMaterial.THAUMIUM,true);golem.setNoAi(true);var saved=new net.minecraft.nbt.CompoundTag();golem.addAdditionalSaveData(saved);saved.putString("deco","HG");golem.readAdditionalSaveData(saved);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_UPGRADES.get(4).get()));golem.interact(player,InteractionHand.MAIN_HAND);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_BELL.get()));golem.moveTo(.5,65,.5);}
 case 3->{l.setBlockAndUpdate(O.west(3),R3Content.ENERGIZED_NODE.get().defaultBlockState());var node=(EnergizedNodeBlockEntity)l.getBlockEntity(O.west(3));var raw=new thaumcraft.blocks.AuraNodeBlockEntity(O.west(3),R2Content.AURA_NODE.get().defaultBlockState());raw.initialize(Map.of("aer",25),thaumcraft.api.nodes.NodeState.Type.NORMAL,thaumcraft.api.nodes.NodeState.Modifier.NONE);node.initialize(raw);l.setBlockAndUpdate(O,R3Content.VIS_RELAY.get().defaultBlockState());l.setBlockAndUpdate(O.east(3),R2Content.ARCANE_WORKBENCH.get().defaultBlockState());l.setBlockAndUpdate(O.east(3).above(),R3Content.WORKBENCH_CHARGER.get().defaultBlockState());((thaumcraft.blocks.TableBlockEntity)l.getBlockEntity(O.east(3))).setItem(10,new ItemStack(R3Equipment.WAND.get()));thaumcraft.api.visnet.VisNetHandler.invalidate(l);player.teleportTo(4.5,67,8.5);}
 case 4->{var bp=O;l.setBlockAndUpdate(bp,R3Content.BORE_BASE.get().defaultBlockState());l.setBlockAndUpdate(bp.above(),R3Content.BORE.get().defaultBlockState().setValue(ArcaneBoreBlock.FACING,Direction.NORTH));l.setBlockAndUpdate(bp.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());var b=(ArcaneBoreBlockEntity)l.getBlockEntity(bp.above());b.items.setItem(0,new ItemStack(R3Equipment.FOCI.get("excavation").get()));b.items.setItem(1,new ItemStack(Items.DIAMOND_PICKAXE));for(int x=-3;x<=3;x++)for(int y=0;y<5;y++)l.setBlockAndUpdate(O.offset(x,y,-4),Blocks.OBSIDIAN.defaultBlockState());player.teleportTo(2.8,65.4,1.5);}
 case 5->{for(int x=-2;x<=2;x++)for(int y=0;y<4;y++)l.setBlockAndUpdate(O.offset(x,y,0),Blocks.OBSIDIAN.defaultBlockState());var w=Round3Verification.wand();WandFocus.set(w,new ItemStack(R3Equipment.FOCI.get("excavation").get()));player.setItemInHand(InteractionHand.MAIN_HAND,w);}
 case 6->{var cow=EntityType.COW.create(l);cow.moveTo(.5,65,-2.5);cow.setNoAi(true);l.addFreshEntity(cow);var w=Round3Verification.wand();WandFocus.set(w,new ItemStack(R3Equipment.FOCI.get("hellbat").get()));player.setItemInHand(InteractionHand.MAIN_HAND,w);}
 case 7->{trunk=R3Entities.TRUNK.get().create(l);trunk.owner(player);trunk.moveTo(.5,65,.5);trunk.setNoAi(true);l.addFreshEntity(trunk);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_UPGRADES.get(5).get()));trunk.interact(player,InteractionHand.MAIN_HAND);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);}
 case 8->{player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("thaumcraft:thaumonomicon"))));player.getMainHandItem().getItem().use(l,player,InteractionHand.MAIN_HAND);}
 case 9->{player.setGameMode(GameType.CREATIVE);player.setItemInHand(InteractionHand.MAIN_HAND,Round3Verification.wand());}
 case 10->{var zombie=EntityType.ZOMBIE.create(l);zombie.moveTo(.5,65,.5);zombie.setNoAi(true);zombie.setInvulnerable(true);l.addFreshEntity(zombie);}
 case 11->{player.setGameMode(GameType.SURVIVAL);for(var effect:List.of(thaumcraft.effects.TaintEffects.FLUX_TAINT,thaumcraft.effects.TaintEffects.VIS_EXHAUST,thaumcraft.effects.WarpEffects.THAUMARHIA,thaumcraft.effects.WarpEffects.UNNATURAL_HUNGER,thaumcraft.effects.WarpEffects.SUN_SCORNED,thaumcraft.effects.WarpEffects.INFECTIOUS_EXHAUST,thaumcraft.effects.WarpEffects.DEATH_GAZE,thaumcraft.effects.WarpEffects.BLURRED_VISION,thaumcraft.effects.WarpEffects.WARP_WARD))player.addEffect(new net.minecraft.world.effect.MobEffectInstance(effect,12000,0));}
 case 12->{l.setBlockAndUpdate(O.above(2),R3Content.INFUSION_MATRIX.get().defaultBlockState());for(int sign:new int[]{-1,1}){l.setBlockAndUpdate(O.offset(sign*3,0,0),R3Content.ARCANE_PEDESTAL.get().defaultBlockState());l.setBlockAndUpdate(O.offset(0,0,sign*3),Blocks.SKELETON_SKULL.defaultBlockState());}player.server.getCommands().performPrefixedCommand(player.createCommandSourceStack(),"thaumcraft debug infusion on");}
 }
 player.inventoryMenu.broadcastChanges();
 }
}
